#include <bits/stdc++.h>
using namespace std;

int invnum(const std::vector<int>& sequence) {
    int count = 0;
    int len = sequence.size();
    for (int i = 0; i < len; ++i) {
        for (int j = i + 1; j < len; ++j) {
            if (sequence[i] > sequence[j]) {
                count++;
            }
        }
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;

    // Initialize dp: 3D vector of size (n+1) x 2 x (2*max_inv+1)
    int max_inv = n * (n - 1) / 2;
    int offset = max_inv + 1; // offset for negative k
    std::vector<std::vector<std::vector<int>>> dp(n + 1, std::vector<std::vector<int>>(2, std::vector<int>(2 * max_inv + 1, -1)));

    // Recursive function with memoization
    std::function<int(int, int, int)> solve = [&](int N, int K, int flag) -> int {
        if (K < -max_inv) K = -max_inv;
        if (K > max_inv) return 0;
        if (dp[N][flag][K + offset] != -1) {
            return dp[N][flag][K + offset];
        }
        if (N == 1) {
            int res = 0;
            if (!flag) {
                res = (K < 0) ? 1 : 0;
            } else {
                res = 0;
            }
            dp[N][flag][K + offset] = res;
            return res;
        }
        int total = 0;
        for (int delta = -N + 1; delta < N; ++delta) {
            if (flag && delta > 0) continue;
            int weight = std::min(N - delta, delta + N);
            int next_flag = flag && (delta == 0);
            total += (long long)solve(N - 1, K - delta, next_flag) * weight % mod;
            total %= mod;
        }
        dp[N][flag][K + offset] = total;
        return total;
    };

    int answer = solve(n, 0, 1) % mod;
    cout << answer << "\n";

    return 0;
}
